import React from "react";
import { useParams, useNavigate } from "react-router-dom";

const jobData = {
  1: {
    title: "Frontend Developer",
    details:
      "Full job description: Build responsive web apps, collaborate with backend, ensure high performance, maintain code quality.",
  },
  2: {
    title: "Backend Engineer",
    details:
      "Full job description: Design scalable APIs, manage databases, implement business logic, and collaborate with frontend.",
  },
};

export default function JobDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const job = jobData[id];

  if (!job) return <p>Job not found</p>;

  return (
    <div className="job-details-container">
      <h2>{job.title}</h2>
      <p>{job.details}</p>
      <button className="apply-btn" onClick={() => navigate(`/apply/${id}`)}>
        Apply Now
      </button>
    </div>
  );
}
